<script lang="ts">
 import {tick} from 'svelte';import {base} from '$app/paths';import {marked} from 'marked';
 import GameCard from '$lib/components/GameCard.svelte';import Accessories from '$lib/components/Accessories.svelte';
 import {allCards,kindNames,type Card} from '$lib/data/game';
 let kind=$state('all'), query=$state(''), backs=$state(false), selected=$state<Card|null>(null), dialog:HTMLDialogElement;
 let visible=$derived(allCards.filter(c=>(kind==='all'||c.kind===kind)&&`${c.name} ${c.title} ${c.copy}`.toLowerCase().includes(query.toLowerCase())));
 async function inspect(card:Card){selected=card;await tick();dialog.showModal();}
</script>
<svelte:head><title>Component gallery — Heaven’s Gate</title><meta name="description" content="Inspect all twelve Angels, ten Heavenly Decrees, five Final Judgments, and printable table accessories."/></svelte:head>
<main id="main" class="gallery-main"><section class="page-intro"><p class="eyebrow">THE HEAVENLY COLLECTION</p><h1>Every soul has its place.</h1><p>Twelve Angels, ten Heavenly Decrees, five Final Judgments.<br/>Select a card to inspect its artwork and complete rules.</p><div class="actions"><a class="text-link" href={`${base}/gallery/print`}>Make a printable set</a><a class="text-link" href={`${base}/downloads/heavens-gate-layered-art.zip`} download>Download layered artwork · 26 MB</a></div></section>
 <section aria-label="Component collection"><div class="gallery-controls"><nav class="tabs" aria-label="Component categories">{#each [['all','All cards · 27'],['angel','Angels · 12'],['decree','Decrees · 10'],['judgment','Judgments · 5'],['accessories','Table essentials']] as [value,label]}<button aria-pressed={kind===value} onclick={()=>kind=value}>{label}</button>{/each}</nav><div class="search-row"><label>Search<input type="search" bind:value={query} placeholder="Name, power, or rule"/></label><label class="checkbox"><input type="checkbox" bind:checked={backs}/>Show card backs</label></div></div>
 {#if kind==='accessories'}<div class="accessory-gallery"><Accessories type="favor"/><Accessories type="zones"/><Accessories type="score"/></div><p class="accessory-note">Bring a standard 106-tile Rummikub set, racks, an opaque bag, five coins, and pencils. Use separate rack space for Scales commitments. No replacement tiles or racks need printing.</p><a class="button" href={`${base}/downloads/heavens-gate-accessories-a4.pdf`} download>Download table essentials</a>
 {:else}<p class="result-count" aria-live="polite">{visible.length} cards</p><div class="gallery-grid">{#each visible as card (card.id)}<div class="gallery-item"><div class="card-wrap"><GameCard {card} back={backs}/><button onclick={()=>inspect(card)} aria-label={`Inspect ${card.name}`}></button></div><p><span>{kindNames[card.kind]}</span><strong>{card.name}</strong></p></div>{:else}<div class="empty-state"><h2>No cards found.</h2><p>Try another name, power, or rule.</p><button onclick={()=>{query='';kind='all';}}>Reset filters</button></div>{/each}</div>{/if}
 </section>
</main>
<dialog bind:this={dialog} onclose={()=>selected=null}><button class="close-dialog" onclick={()=>dialog.close()}>Close ×</button>{#if selected}<div class="inspection"><div class="inspection-card"><GameCard card={selected} back={backs}/></div><div class="inspection-copy"><p class="eyebrow">{kindNames[selected.kind]}</p><h2>{selected.name}</h2><div class="prose">{@html marked.parse(selected.rule) as string}</div><a href={`${base}/art/layers/${backs?'back-'+selected.kind:selected.id}.svg`} download>Download layered SVG source</a></div></div>{/if}</dialog>
